"""Tamil Jaffna travel examples; all supplier arrangements require confirmation."""
TAMIL_QUESTIONS = [
    ("first_visit", "யாழ்ப்பாணத்துக்கு முதல் தடவையாக வருகிறோம். எதைப் பார்க்கலாம்?", "கோட்டை, நல்லூர் பகுதி, உள்ளூர் சந்தை மற்றும் பாரம்பரிய உணவு ஆகியவற்றை மையமாகக் கொண்ட பயணத்தை முன்மொழியலாம்; அணுகலும் ஏற்பாடுகளும் உறுதிப்படுத்தப்பட வேண்டும். எத்தனை நாட்கள் தங்குவீர்கள்?", "ஒரு நாள் மட்டும்தான்.", "ஒரு நாளுக்கு யாழ்ப்பாணத்தை மையமாகக் கொண்ட நிதானமான திட்டத்தை அமைக்கலாம். எத்தனை பேர் வருகிறீர்கள்?"),
    ("family", "இரண்டு பெரியவர்களும் இரண்டு குழந்தைகளும் பாட்டியும் வருகிறோம். இரண்டு நாட்கள் இருக்கிறோம்.", "ஐந்து பேருக்கான நிதானமான இரண்டு நாள் திட்டத்தில் உணவு, கைவினை மற்றும் ஓய்வு இடைவெளிகளை முன்னிலைப்படுத்தலாம். பாட்டிக்கு நடப்பது அல்லது படிகள் ஏறுவது சிரமமா?", "நீண்ட நேரம் நடக்க முடியாது. படகுப் பயணமும் வேண்டாம்.", "நீண்ட நடைப்பயணமும் படகும் இல்லாத நிலப்பகுதி திட்டத்தைக் கோருகிறேன்; இடங்களின் அணுகலைச் சரிபார்க்க வேண்டும். நீங்கள் வரும் தேதிகள் என்ன?"),
    ("group_price", "பன்னிரண்டு பேருக்கு விலைக் கழிவு கிடைக்குமா?", "குழுவிற்கான தனி விலைப்புள்ளியைக் கோரலாம்; வழங்குநர் உறுதிப்படுத்தாமல் விலைக் கழிவு இருப்பதாகக் கூற முடியாது. பன்னிரண்டு பேரும் பெரியவர்களா?", "பத்து பெரியவர்கள், இரண்டு குழந்தைகள்.", "அந்த எண்ணிக்கையைப் பதிவு செய்து குழந்தைகளுக்கான கட்டணத்தையும் தனியாகக் கோரலாம். குழந்தைகளின் வயது என்ன?"),
    ("price_basis", "ஒரு நாள் பயணம் 8,000 முதல் 18,000 ரூபாய் என்றால் அது முழுக் குடும்பத்துக்குமா?", "ஆவணத்தில் அந்த உத்தேச வரம்பு ஒரு நபருக்கானது; அது முழுக் குடும்பத்தின் உறுதிப்படுத்தப்பட்ட கட்டணம் அல்ல. எத்தனை பெரியவர்களும் குழந்தைகளும் வருகிறார்கள்?", "இரண்டு பெரியவர்கள், இரண்டு குழந்தைகள்.", "குழந்தைகளின் வயதும் தற்போதைய வழங்குநர் விலைகளும் தெரிந்த பிறகே குடும்பத்தின் மொத்த விலையை உறுதிப்படுத்தலாம். குழந்தைகளின் வயது என்ன?"),
    ("paddy_planting", "நெல் நடவு செய்து பார்க்க முடியுமா?", "விவசாயியின் அனுமதியும் பொருத்தமான நடவுக் காலமும் இருந்தால் நெல் நடவு அனுபவத்தை ஏற்பாடு செய்யக் கோரலாம். எப்போது வர நினைக்கிறீர்கள்?", "அடுத்த வாரம். தேதி மாற்ற முடியாது.", "அடுத்த வாரத்திற்கான வயல் நிலைமையையும் விவசாயியின் நேரத்தையும் உறுதிப்படுத்த வேண்டும். நடவு கிடைக்காவிட்டால் கைவினைப் பயிற்சி மாற்றாகப் பொருந்துமா?"),
    ("harvest", "வருடம் முழுவதும் நெல் அறுவடை பார்க்க முடியுமா?", "முடியாது; அறுவடை உண்மையான பயிர் நிலைமையையும் காலத்தையும் பொறுத்தது. நீங்கள் வரவிருக்கும் மாதம் எது?", "டிசம்பர்.", "டிசம்பரில் பங்கேற்கும் விவசாயியிடம் அறுவடை இருப்பதைச் சரிபார்க்க வேண்டும்; அதை இப்போது உறுதி செய்ய முடியாது. மாற்றாக கிராம உணவு அல்லது கைவினை அனுபவம் வேண்டுமா?"),
    ("craft", "பனை ஓலைக் கைவினை செய்து அதை வீட்டுக்கு எடுத்துச் செல்ல முடியுமா?", "கலைஞர், பொருட்கள் மற்றும் நேரம் உறுதிப்படுத்தப்பட்டால் பனை ஓலைக் கைவினைப் பயிற்சியைக் கோரலாம்; செய்து முடித்த பொருளை எடுத்துச் செல்ல முடியுமா என்பதையும் சரிபார்க்க வேண்டும். எத்தனை பேர் பங்கேற்பீர்கள்?", "நான்கு பேர். குழந்தைகளும் இருக்கிறார்கள்.", "நான்கு பேருக்கும் ஏற்ற பயிற்சியை கலைஞரிடம் கேட்கலாம். குழந்தைகளின் வயது என்ன?"),
    ("cooking", "யாழ்ப்பாண உணவைச் சமைத்துப் பார்க்க விரும்புகிறேன். சைவ உணவு மட்டும் வேண்டும்.", "சந்தைப் பயணமும் சைவ சமையல் அனுபவமும் கோரலாம்; உணவுப் பொருட்களையும் தயாரிப்பு முறையையும் ஏற்பாட்டாளர் உறுதிப்படுத்த வேண்டும். தனிப் பாத்திரங்கள் வேண்டுமா?", "ஆம், தனிப் பாத்திரங்கள் வேண்டும்.", "சைவ உணவும் தனிப் பாத்திரங்களும் உங்கள் கோரிக்கையாகப் பதிவு செய்கிறேன். எத்தனை பேர் பங்கேற்பார்கள்?"),
    ("allergy", "எனக்கு கடல் உணவு ஒவ்வாமை இருக்கிறது. நண்டு சமையலில் கலந்து கொள்ளலாமா?", "நண்டு சமையலில் கடல் உணவுடன் தொடர்பு ஏற்படலாம்; ஒவ்வாமை இல்லாத சூழல் என்று உறுதி செய்ய முடியாது. மாற்றாக சைவ சமையலைத் திட்டத்தில் சேர்க்க விரும்புகிறீர்களா?", "ஆம், அனைவருக்கும் சைவம் வேண்டும்.", "அனைவருக்கும் சைவ உணவைக் கோருகிறேன்; பொருட்களையும் கலப்புத் தொடர்பு ஏற்படாத நடைமுறைகளையும் வழங்குநர் சரிபார்க்க வேண்டும். எத்தனை பேர் வருகிறீர்கள்?"),
    ("island", "நயினாதீவுக்கும் நல்லூருக்கும் செல்ல விரும்புகிறோம்.", "அந்த இடங்களை மையமாகக் கொண்ட முன்மொழிவை அமைக்கலாம்; கோவில் அணுகல், படகுச் சேவை மற்றும் காலநிலை உறுதிப்படுத்தப்பட வேண்டும். எத்தனை நாட்கள் இருக்கிறீர்கள்?", "இரண்டு நாட்கள்.", "இரண்டு நாட்களுக்கு நிதானமான திட்டத்தை முன்மொழியலாம்; தீவுப் பயணத்தை இப்போது உறுதி செய்ய முடியாது. நீங்கள் வரும் தேதிகள் என்ன?"),
    ("boat_weather", "நாளைக்கு படகு நிச்சயமாகச் செல்லுமா?", "நாளைய படகுப் பயணத்தை உறுதி செய்ய முடியாது; காலநிலை, இயக்குநர் மற்றும் இறங்கும் அனுமதியைச் சரிபார்க்க வேண்டும். நிலப்பகுதி மாற்றுத் திட்டத்தையும் சேர்க்க விரும்புகிறீர்களா?", "ஆம், உணவும் கைவினையும் போதும்.", "உணவும் கைவினையும் மாற்றுத் திட்டமாகக் கோருகிறேன்; ஏற்பாட்டாளர்களின் நேரம் உறுதிப்படுத்தப்பட வேண்டும். எத்தனை பேர் பங்கேற்பார்கள்?"),
    ("proposal", "என் காதலிக்கு தெரியாமல் திருமண முன்மொழிவு ஏற்பாடு செய்ய வேண்டும்.", "தனிப்பட்ட முன்மொழிவு ஏற்பாட்டைக் கோரலாம்; இட அனுமதி, அலங்காரம் மற்றும் வழங்குநர் கிடைப்பை உறுதிப்படுத்த வேண்டும். கடற்கரை இடமா அல்லது தனி உணவு இடமா விரும்புகிறீர்கள்?", "தனி உணவு இடம். அவளுக்கு இதைச் சொல்ல வேண்டாம்.", "ரகசியமாக வைத்திருக்க வேண்டிய கோரிக்கையையும் தனி உணவு இட விருப்பத்தையும் பதிவு செய்கிறேன். உங்கள் செலவுத் திட்டம் என்ன?"),
    ("photos", "எங்கள் புகைப்படங்களை சமூக வலைத்தளங்களில் போட வேண்டாம்.", "புகைப்படங்களை வெளியிடக்கூடாது என்ற கோரிக்கையைப் பதிவு செய்து புகைப்படக் கலைஞரின் ஒப்புதலைக் கேட்கலாம். இது குழுவிலுள்ள அனைவருக்கும் பொருந்துமா?", "ஆம், அனைவருக்கும்.", "முழுக் குழுவிற்கும் வெளியிடாத தனியுரிமைக் கோரிக்கையைப் பதிவு செய்கிறேன். தனிப்பட்ட இணைப்பின் மூலம் படங்களைப் பெற விரும்புகிறீர்களா?"),
    ("female_guide", "பெண் வழிகாட்டி கிடைக்குமா? தமிழ் பேச வேண்டும்.", "தமிழ் பேசும் பெண் வழிகாட்டியைக் கோரலாம்; கிடைப்பதை வழங்குநர் உறுதிப்படுத்த வேண்டும். உங்கள் பயணத் தேதிகள் என்ன?", "அடுத்த மாதம், தேதிகள் மாற்றிக்கொள்ளலாம்.", "தேதிகள் மாற்றிக்கொள்ளக்கூடியவை என்ற தகவலுடன் வழிகாட்டியின் கிடைப்பைச் சரிபார்க்கலாம். எத்தனை நாள் பயணம் வேண்டும்?"),
    ("wheelchair", "அப்பா சக்கர நாற்காலி பயன்படுத்துகிறார். அவரும் வர முடியுமா?", "ஒவ்வொரு இடத்திலும் படியில்லா அணுகல், கழிப்பறை மற்றும் பொருத்தமான வாகன வசதிகளை உறுதிப்படுத்த வேண்டும். பயணத்தின்போதும் சக்கர நாற்காலியிலேயே இருக்க வேண்டுமா?", "ஆம். படகுப் பயணம் வேண்டாம்.", "பொருத்தமான வாகனமும் படகு இல்லாத நிலப்பகுதி திட்டமும் கோருகிறேன்; கிடைப்பதை உறுதிப்படுத்த வேண்டும். எத்தனை பேர் வருகிறீர்கள்?"),
    ("refund", "ரத்து செய்தால் முழுப் பணமும் திரும்பக் கிடைக்குமா?", "பணம் திரும்ப வழங்கப்படுவது எழுத்திலுள்ள ரத்து விதிகளையும் காலக்கெடுவையும் பொறுத்தது; முழுத் தொகையையும் உறுதி செய்ய முடியாது. ஏற்கெனவே பணம் செலுத்தியுள்ளீர்களா?", "இல்லை, இன்னும் தேர்வு செய்கிறோம்.", "பணம் செலுத்துவதற்கு முன் ரத்து காலக்கெடுவையும் திரும்ப வழங்கப்படாத கட்டணங்களையும் கேட்டறியுங்கள். மாற்றிக்கொள்ளக்கூடிய விதிகள் உங்களுக்கு முக்கியமா?"),
    ("pickup", "யாழ்ப்பாண ரயில் நிலையத்தில் எங்களை அழைத்துச் செல்ல முடியுமா?", "ரயில் நிலையத்தில் அழைத்துச் செல்லும் சேவையைக் கோரலாம்; நேரம், வாகனம் மற்றும் கட்டணம் உறுதிப்படுத்தப்பட வேண்டும். எத்தனை மணிக்கு வருவீர்கள்?", "காலை எட்டு மணிக்கு, நான்கு பேர்.", "காலை எட்டு மணிக்கு நான்கு பேருக்கான நிலைய அழைத்துச் செல்லும் கோரிக்கையைப் பதிவு செய்கிறேன். உங்கள் பயணத் தேதி என்ன?"),
    ("correction", "மூன்று நாட்கள், நான்கு நண்பர்கள், உணவும் கலாசாரமும் வேண்டும்.", "நான்கு நண்பர்களுக்கு மூன்று நாள் உணவு மற்றும் கலாசாரப் பயணத்தை மையமாகக் கொள்ளலாம். உங்கள் மொத்த செலவுத் திட்டம் என்ன?", "உண்மையில் ஆறு பேர். கடல் உணவு வேண்டாம்.", "மூன்று நாட்கள் என்ற தகவலை வைத்துக்கொண்டு ஆறு பேர் என்றும் கடல் உணவு வேண்டாம் என்றும் புதுப்பிக்கிறேன். உங்கள் மொத்த செலவுத் திட்டம் என்ன?"),
    ("multi_district", "மூன்று நாட்களில் யாழ்ப்பாணம், மன்னார், முல்லைத்தீவு எல்லாம் பார்க்கலாமா?", "அனைத்தையும் சேர்த்தால் அவசரமான பயணமாகலாம்; மாவட்டத்தை மையமாகக் கொண்ட நிதானமான பாதை சிறந்தது. யாழ்ப்பாணத்தை மையமாகக் கொண்ட திட்டமா அல்லது அதிக நாட்களுடன் விரிவான திட்டமா வேண்டும்?", "யாழ்ப்பாணமும் கிராம அனுபவமும் போதும்.", "யாழ்ப்பாண மரபு, உணவு மற்றும் ஏற்பாடு செய்யப்பட்ட கிராம அனுபவத்தை முன்னிலைப்படுத்தலாம். எத்தனை பேர் பங்கேற்பீர்கள்?"),
    ("tanglish_price", "Konjam vilai kuraikka mudiyuma? Couple trip than venum.", "ஜோடி பயணத்தின் நோக்கத்தை மாற்றாமல் செலவு குறைந்த விருப்பங்களை ஒப்பிடலாம்; தள்ளுபடியை உறுதி செய்ய முடியாது. இருவருக்கான மொத்த செலவுத் திட்டம் என்ன?", "40,000 rupees. Private transport mukkiyam.", "இருவருக்கு 40,000 ரூபாயும் தனிப்பட்ட வாகனமும் முன்னுரிமையாகப் பதிவு செய்கிறேன். கூடுதல் சேவைகளைக் குறைக்க விரும்புகிறீர்களா?"),
    ("tanglish_privacy", "En girlfriend-ku crowd pidikkathu. Quiet-a irukkanum.", "அமைதியான இடங்களையும் தனிப்பட்ட ஏற்பாடுகளையும் கோரலாம்; பொது இடங்களில் யாரும் இருக்க மாட்டார்கள் என்று உறுதி செய்ய முடியாது. வழிகாட்டியுடன் உரையாடலையும் குறைக்க வேண்டுமா?", "Aama, konjam privacy venum.", "குறைந்த உரையாடலும் தனியுரிமையும் உங்கள் விருப்பங்களாகப் பதிவு செய்கிறேன். அமைதியான உணவு இடம் வேண்டுமா?"),
]
